import {clamp} from './touch-utils.js';
export const GRAVITY_MODES={race:'Gravity Race',orbs:'Orb Challenge',survival:'Survival Chaos'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seconds=t=>(t/1000).toFixed(1)+'s';
export function openGravity(host,{exit,notify,ask,initialPage='setup'}){
 const $=s=>host.querySelector(s);let difficulty=3,level=1,mode='race',versus=false,series=5,ids=[DB.active,DB.profiles.find(p=>p.id!==DB.active)?.id],worlds=[],phase='setup',page='setup',paused=false,disposed=false,last=0,raf=0,round=0,wins=[0,0],rounds=[],committed=false,recordInfo=[],ranked=true,lastSound=0;
 host.innerHTML=`<section class="new-arcade gravity-room"><header class="new-header"><button class="btn secondary" id="gravityExit">⌂ ARCADE</button><div><span class="eyebrow">NEON ARCADE UNIVERSE · PHYSICS IN MOTION</span><h1>🪐 Gravity Chaos</h1></div><nav><button class="btn secondary" id="gravitySetup">SETUP</button><button class="btn secondary" id="gravityRecords">♛ RECORDS</button><button class="icon-btn" id="gravityMute" aria-label="Mute sound">♪</button><button class="icon-btn" id="gravityFull" aria-label="Fullscreen">⛶</button></nav></header><div id="gravityContent"></div></section>`;
 const content=$('#gravityContent'),observer=new ResizeObserver(()=>resize());$('#gravityFull').onclick=()=>document.getElementById('fullscreen')?.click();$('#gravityMute').onclick=()=>{document.getElementById('mute')?.click();$('#gravityMute').textContent=DB.settings.muted?'♪̸':'♪';};
 async function leave(action){if(page==='play'&&['play','ready'].includes(phase)){pause(true);if(!await ask('Leave Gravity Chaos?','Unfinished runs do not change scores, stars or match records.')){pause(false);return;}}disposeWorlds();action();}
 $('#gravityExit').onclick=()=>leave(exit);$('#gravitySetup').onclick=()=>leave(setup);$('#gravityRecords').onclick=()=>leave(records);
 function disposeWorlds(){worlds.forEach(w=>w.dispose());worlds=[];observer.disconnect();}
 function options(selected){return DB.profiles.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${p.avatar} ${esc(p.name)}</option>`).join('');}
 const gate=createInstructionGate({game:'gravity',onBack:exit,onReview:()=>pause(true)});
 function requestSession(){gate.show({players:(versus?ids:ids.slice(0,1)).map(id=>player(id).name),difficulty:LEVELS[difficulty-1],mode,modeLabel:GRAVITY_MODES[mode]},()=>startRound(true));}
 function setup(){disposeWorlds();page='setup';phase='setup';paused=false;content.innerHTML=`<div class="new-setup gravity-setup"><section class="new-intro"><span class="eyebrow">FLIP THE FORCE. FIND YOUR FLOW.</span><h2>Your hands.<br><em>The laws of motion.</em></h2><div class="gravity-poster">${gravityArt()}</div><p>Swipe up, down, left or right to change gravity. The ball keeps its momentum. Drag platforms, rotate them with two fingers, tap switches and bumpers, hold the safety field, or draw an energy ramp inside its marked zone.</p><div class="gravity-features">30 COURSES · REAL MATTER.JS PHYSICS · INDEPENDENT MULTITOUCH</div></section><section class="panel new-options"><div class="mode-toggle"><button data-gravity-count="1" class="${!versus?'selected':''}">☺ 1 Player</button><button data-gravity-count="2" class="${versus?'selected':''}" ${DB.profiles.length<2?'disabled':''}>⚔ 2 Players</button></div><div class="form-columns"><label>Player 1<select id="gravityP1">${options(ids[0])}</select></label>${versus?`<label>Player 2<select id="gravityP2">${options(ids[1])}</select></label>`:''}</div><label>Challenge<select id="gravityMode">${Object.entries(GRAVITY_MODES).map(([key,title])=>`<option value="${key}" ${mode===key?'selected':''}>${title}</option>`).join('')}</select></label>${versus?`<label>Match length<select id="gravitySeries"><option value="1" ${series===1?'selected':''}>Single round</option><option value="5" ${series===5?'selected':''}>Best of five · first to three</option></select></label>`:''}<label>DIFFICULTY <b id="gravityDiffName">${LEVELS[difficulty-1]}</b><input id="gravityDifficulty" type="range" min="1" max="5" value="${difficulty}" aria-label="Difficulty"></label><button class="btn secondary" id="gravityLevels">▦ LEVEL ${level} · ${GRAVITY_LEVELS[level-1].name}</button><p class="gravity-note">${mode==='survival'?'Survive 75 seconds. Sweeping chaos waves cannot be disabled by the safety field. Hazards grow faster. Three lives.':mode==='orbs'?'Both players get time to finish. Completed runs rank first; most orbs wins, then fastest completion.':'Reach the goal first. Time, then orbs and gravity changes break ties.'} ${difficulty===5?'Expert runs allow four mistakes; restart for unlimited new attempts.':difficulty===4?'Selected later levels have a gravity-change budget.':'Unlimited gravity changes.'}</p><div class="intro-fairness">${versus?'Separate physics worlds · identical layouts · independent gravity':'All 30 levels work at every difficulty · automatic saved records'}</div><button class="btn primary full" id="gravityLaunch">${versus?'START THE MATCH ⚔':'LET’S PLAY →'}</button></section></div>`;
 content.querySelectorAll('[data-gravity-count]').forEach(b=>b.onclick=()=>{versus=b.dataset.gravityCount==='2';setup();});$('#gravityP1').onchange=e=>ids[0]=e.target.value;if($('#gravityP2'))$('#gravityP2').onchange=e=>ids[1]=e.target.value;$('#gravityMode').onchange=e=>{mode=e.target.value;setup();};if($('#gravitySeries'))$('#gravitySeries').onchange=e=>series=+e.target.value;$('#gravityDifficulty').oninput=e=>{difficulty=+e.target.value;$('#gravityDiffName').textContent=LEVELS[difficulty-1];};$('#gravityDifficulty').onchange=setup;$('#gravityLevels').onclick=levels;
 $('#gravityLaunch').onclick=()=>{ids[0]=$('#gravityP1').value;if(versus){ids[1]=$('#gravityP2').value;if(ids[0]===ids[1]){notify('Choose two different players.');return;}}DB.active=ids[0];save();round=0;wins=[0,0];rounds=[];committed=false;requestSession();};
 }
 function levels(){page='levels';phase='setup';content.innerHTML=`<div class="new-levels"><div class="page-heading"><div><span class="eyebrow">30 DESIGNED COURSES · ${LEVELS[difficulty-1].toUpperCase()}</span><h2>Find your next orbit.</h2><p>All levels are playable at every difficulty. Stars and records stay separated.</p></div><button class="btn secondary" id="gravityBackSetup">← SETUP</button></div><div class="gravity-levels">${GRAVITY_LEVELS.map(l=>{const records=player(ids[0]).results.filter(r=>r.game==='gravity'&&r.difficulty===difficulty&&r.mode==='solo'&&r.levelId==='level-'+l.id),ds=records.flatMap(r=>r.details?.rounds||[r.details]).filter(Boolean),stars=Math.max(0,...ds.map(d=>d.stars||0)),best=Math.min(Infinity,...ds.filter(d=>d.completed).map(d=>d.clock));return `<button data-gravity-level="${l.id}" class="${level===l.id?'selected':''}"><b>${l.id}</b><span>${l.name}</span><small>${stars?'★'.repeat(stars)+' · '+seconds(best):l.theme}</small></button>`;}).join('')}</div></div>`;$('#gravityBackSetup').onclick=setup;content.querySelectorAll('[data-gravity-level]').forEach(b=>b.onclick=()=>{level=+b.dataset.gravityLevel;setup();});}
 function startRound(acknowledged=false){disposeWorlds();round++;phase='ready';page='play';paused=false;worlds=(versus?ids:ids.slice(0,1)).map(()=>new GravityWorld({level,difficulty,mode}));buildPlay();const o=$('#gravityOverlay');o.hidden=false;o.innerHTML=`<div class="result-card"><div class="eyebrow">${versus?'IDENTICAL COURSES · INDEPENDENT GRAVITY':'A NEW WAY TO MOVE'}</div><h2>${mode==='survival'?'Ride out the chaos.':'Ready to flip gravity?'}</h2><p>Swipe anywhere empty on your board. Gold energy orbs are required on later courses; pale orbs are bonuses. Tap the A switch before passing its gate. Hold SAFETY FIELD to disable standard lasers and timed doors.</p><button class="btn primary" id="gravityBegin">POWER UP →</button></div>`;$('#gravityBegin').onclick=begin;last=performance.now();begin();}
 function begin(){phase='play';paused=false;$('#gravityOverlay').hidden=true;last=performance.now();audio();fx('go');}
 function playing(){return page==='play'&&phase==='play'&&!paused;}
 function buildPlay(){content.innerHTML=`<div class="new-play gravity-play"><div class="new-matchbar"><span>${GRAVITY_MODES[mode]} · ${LEVELS[difficulty-1]} · LEVEL ${level}${versus?' · ROUND '+round+' · '+wins.join(' : '):''}</span><div><button class="btn secondary" id="gravityPause">Ⅱ PAUSE</button><button class="btn accent" id="gravityRestart">↻ RESTART</button></div></div><div class="new-playfield ${versus?'circuit-split':''}">${worlds.map((w,i)=>`<section class="new-zone gravity-zone" style="--player:${player(ids[i]).color}"><div class="gravity-hud" data-gravity-hud="${i}"></div><div class="gravity-objective" data-gravity-objective="${i}"></div><div class="new-canvas-wrap"><canvas data-gravity-canvas="${i}" aria-label="${esc(player(ids[i]).name)} Gravity Chaos play area"></canvas></div><div class="gravity-tools" data-gravity-tools="${i}"><button class="gravity-tool selected" data-gravity-tool="gravity" data-owner="${i}"><b>↕</b><span>SWIPE GRAVITY</span></button><button class="gravity-tool" data-gravity-tool="ramp" data-owner="${i}" ${!w.level.rampZone?'disabled':''}><b>╱</b><span>DRAW RAMP</span></button><button class="gravity-tool" data-rotate="${i}" ${!w.platforms.some(b=>b.plugin.gravity.rotatable)?'disabled':''}><b>⟳</b><span>ROTATE 15°</span></button><button class="gravity-tool safety" data-safety="${i}" ${level<11?'disabled':''}><b>◌</b><span>HOLD SAFETY</span></button><button class="gravity-tool" data-energy-shield="${i}" disabled><b>⬡</b><span>SHIELD ×0</span></button><button class="gravity-tool" data-gravity-retry="${i}"><b>↺</b><span>RETRY BALL</span></button></div><div class="new-help" data-gravity-help="${i}"></div></section>`).join('')}</div><div class="new-overlay" id="gravityOverlay" hidden></div></div>`;
 $('#gravityPause').onclick=()=>pause(!paused);$('#gravityRestart').onclick=async()=>{if(versus){pause(true);if(!await ask('Restart the match?','Unfinished rounds will be discarded. Saved records stay intact.')){pause(false);return;}}round=0;rounds=[];wins=[0,0];committed=false;startRound(true);};
 worlds.forEach((w,i)=>{const c=$(`[data-gravity-canvas="${i}"]`);bindCanvas(c,i);const el=$(`[data-gravity-tools="${i}"]`);el.querySelectorAll('[data-gravity-tool]').forEach(b=>b.onclick=()=>{if(!playing())return;w.inputMode=b.dataset.gravityTool;el.querySelectorAll('[data-gravity-tool]').forEach(x=>x.classList.toggle('selected',x===b));w.feedback=w.inputMode==='ramp'?'Draw a line entirely inside the dashed ramp zone.':'Swipe up, down, left or right.';});el.querySelector('[data-rotate]').onclick=()=>{if(playing()&&!w.rotateSelected())w.feedback='Tap or drag a violet platform first, then rotate it.';};el.querySelector('[data-energy-shield]').onclick=()=>{if(playing())w.shield();};el.querySelector('[data-gravity-retry]').onclick=()=>{if(playing())w.retry();};const hold=el.querySelector('[data-safety]');hold.onpointerdown=e=>{if(!playing()||hold.disabled)return;e.preventDefault();hold.setPointerCapture(e.pointerId);w.hold(e.pointerId,true);hold.classList.add('held');};const release=e=>{w.hold(e.pointerId,false);hold.classList.remove('held');};hold.onpointerup=release;hold.onpointercancel=release;hold.onlostpointercapture=release;});
 observer.disconnect();content.querySelectorAll('canvas').forEach(c=>observer.observe(c));resize();
 }
 function point(c,e){const r=c.getBoundingClientRect(),s=Math.min(r.width/1000,r.height/640),x=(r.width-s*1000)/2,y=(r.height-s*640)/2;return{x:clamp((e.clientX-r.left-x)/s,0,1000),y:clamp((e.clientY-r.top-y)/s,0,640)};}
 function bindCanvas(c,i){const owned=new Set();c.onpointerdown=e=>{if(!playing()||worlds[i].done)return;e.preventDefault();const p=point(c,e);if(worlds[i].input('down',p.x,p.y,e.pointerId)){owned.add(e.pointerId);c.setPointerCapture(e.pointerId);}};c.onpointermove=e=>{if(!owned.has(e.pointerId)||!playing())return;e.preventDefault();const p=point(c,e);worlds[i].input('move',p.x,p.y,e.pointerId);};const up=(e,cancel)=>{if(!owned.has(e.pointerId))return;owned.delete(e.pointerId);const p=point(c,e);worlds[i].input(cancel||!playing()?'cancel':'up',p.x,p.y,e.pointerId);if(c.hasPointerCapture(e.pointerId))c.releasePointerCapture(e.pointerId);};c.onpointerup=e=>up(e,false);c.onpointercancel=e=>up(e,true);c.onlostpointercapture=e=>up(e,true);}
 function resize(){content.querySelectorAll('canvas').forEach(c=>prepareCanvas(c));}
 function pause(v){if(page!=='play'||!['play','ready'].includes(phase))return;paused=v;worlds.forEach(w=>w.cancel());if(phase==='play'){const o=$('#gravityOverlay');o.hidden=!v;if(v){o.innerHTML='<div class="result-card"><h2>Gravity paused.</h2><p>Both physics worlds and clocks are resting.</p><button class="btn primary" id="gravityResume">▶ RESUME</button></div>';$('#gravityResume').onclick=()=>pause(false);}$('#gravityPause').textContent=v?'▶ RESUME':'Ⅱ PAUSE';}last=performance.now();}
 function hud(w,i){const d=DIRECTIONS[w.direction],required=w.level.orbs.filter(o=>o.required),powered=required.filter(o=>w.collected.has(o.id)).length;const text=`${w.orbCount}/3 ORBS · ${w.changes} FLIPS${Number.isFinite(w.level.changeLimit)&&mode!=='survival'?' · '+Math.max(0,w.level.changeLimit-w.runChanges)+' LEFT':''} · ${mode==='survival'?'♥ '+w.lives:w.mistakes+' MISTAKES'}`;$(`[data-gravity-hud="${i}"]`).innerHTML=`<span class="gravity-arrow">${d.icon}</span><div><b>${player(ids[i]).avatar} ${esc(player(ids[i]).name)}</b><small>${d.name} GRAVITY · ${text}</small></div><strong>${w.score}<small>${seconds(w.clock)} / ${Math.round(w.duration/1000)}s</small></strong>`;
 $(`[data-gravity-objective="${i}"]`).innerHTML=`<span>${mode==='survival'?'SURVIVE THE CHAOS WAVES':w.goalOpen?'GOAL POWERED — BRING THE BALL HOME':`POWER THE GOAL${required.length?' · GOLD ORBS '+powered+'/'+required.length:''}${w.level.requiredSwitch?' · SWITCH A '+(w.switches.has('A')?'✓':'OFF'):''}`}</span><i style="--gravity-progress:${Math.min(100,(mode==='survival'?w.clock/w.duration:(w.orbCount+(w.complete?3:0))/6)*100)}%"></i>`;
 $(`[data-gravity-help="${i}"]`).textContent=w.feedback;const shield=$(`[data-energy-shield="${i}"]`);shield.disabled=!w.shieldCharges||w.done;shield.querySelector('span').textContent='SHIELD ×'+w.shieldCharges;
 }
 function frame(now){if(disposed)return;const dt=Math.max(0,Math.min(250,now-last));last=now;if(page==='play'){
 if(playing()){worlds.forEach(w=>w.update(dt));for(const w of worlds)for(const e of w.events.splice(0)){if(now-lastSound>55){fx(e==='finish'?'win':e==='bad'?'bad':e==='orb'?'treasure':e==='impact'?'gravity-impact':e==='gravity'?'gravity-flip':'signal');lastSound=now;}}
 const ended=mode==='race'?worlds.some(w=>w.complete)||worlds.every(w=>w.done):worlds.every(w=>w.done);if(ended)endRound();}
 worlds.forEach((w,i)=>{const c=$(`[data-gravity-canvas="${i}"]`);if(c){renderGravity(c,w,player(ids[i]).color);hud(w,i);}});
 }raf=requestAnimationFrame(frame);}
 function entry(i){const w=worlds[i];return{id:ids[i],score:w.score,hits:w.orbCount+(w.changes?Math.floor(w.clock/10000):0),errors:w.mistakes,accuracy:w.accuracy,duration:w.clock/1000,stars:w.stars,completed:w.complete,soloWin:w.complete,details:w.summary()};}
 function endRound(){if(phase!=='play')return;phase='roundresult';worlds.forEach(w=>w.cancel());const entries=worlds.map((_,i)=>entry(i)),cmp=versus?compareGravity(worlds[0],worlds[1],mode):0;if(versus&&cmp)wins[cmp>0?0:1]++;rounds.push(entries);if(!versus||wins.some(w=>w>=Math.ceil(series/2))||round>=series)finishMatch();else results(entries,cmp,false);}
 function finishMatch(){if(committed)return;committed=true;phase='results';const entries=worlds.map((_,i)=>{const rows=rounds.map(r=>r[i]),last=rows.at(-1);return{...last,score:Math.round(rows.reduce((s,e)=>s+e.score,0)/rows.length),hits:rows.reduce((s,e)=>s+e.hits,0),errors:rows.reduce((s,e)=>s+e.errors,0),duration:rows.reduce((s,e)=>s+e.duration,0),details:{...last.details,completed:rows.every(e=>e.details.completed),clock:rows.reduce((s,e)=>s+e.details.clock,0),orbs:rows.reduce((s,e)=>s+e.details.orbs,0),changes:rows.reduce((s,e)=>s+e.details.changes,0),perfect:rows.every(e=>e.details.perfect),rounds:rows.map(e=>e.details),series:versus?series:1,roundWins:wins[i]}};});const cmp=versus?wins[0]-wins[1]:0,winnerId=versus?cmp?ids[cmp>0?0:1]:null:undefined;ranked=entries.some(e=>e.details.rounds.some(d=>d.changes||Object.values(d.interactions).some(Boolean)));recordInfo=commitRound(entries,{game:'gravity',difficulty,learn:false,mode:versus?'versus':'solo',ruleset:'gravity-v1',levelId:'level-'+level,competition:mode,challengeKey:'series-'+(versus?series:1),winnerId,ranked});
 if(ranked){entries.forEach((e,i)=>{const p=player(ids[i]);for(const d of e.details.rounds){if(d.completed)unlock(p,'gravity-rookie');if(d.completed&&d.interactions.up)unlock(p,'gravity-up');if(d.perfect)unlock(p,'gravity-perfect');if(d.completed&&d.orbs===3)unlock(p,'gravity-orbs');}const done=new Set(p.results.filter(r=>r.game==='gravity'&&(r.details?.rounds||[r.details]).some(d=>d?.completed)).map(r=>r.levelId));if(done.size>=30)unlock(p,'gravity-master');if(versus&&winnerId===p.id)unlock(p,'gravity-champion');});save();}fx('win');results(entries,cmp,true);
 }
 function results(entries,cmp,finished){const o=$('#gravityOverlay');o.hidden=false;o.innerHTML=`<div class="result-card wide new-celebration"><div class="eyebrow">${finished?ranked?recordInfo.some(r=>r.pb)?'✦ NEW PERSONAL BEST ✦':'PROGRESS SAVED':'TRY THE GRAVITY CONTROLS':'ROUND '+round+' COMPLETE'}</div><h2>${versus?cmp?esc(player(ids[cmp>0?0:1]).name)+(finished?' wins!':' takes the round!'):'A brilliant tie!':entries[0].details.completed?mode==='survival'?'Chaos conquered!':'Perfectly in orbit!':'Another orbit awaits.'}</h2>${versus?'<p>Match score '+wins.join(' : ')+'</p>':''}<div class="results-grid">${entries.map((e,i)=>`<section><span class="avatar" style="--player:${player(ids[i]).color}">${player(ids[i]).avatar}</span><h3>${esc(player(ids[i]).name)}</h3><div class="big-score">${e.score}<small>${versus&&series>1?'AVG POINTS / ROUND':'POINTS'}</small></div><p>${e.details.completed?'★'.repeat(e.stars||1)+' COMPLETED':'RUN FINISHED'}<br>${e.details.orbs} energy orbs · ${e.details.changes} gravity changes<br>${seconds(e.duration*1000)} active time · ${e.errors} mistakes</p></section>`).join('')}</div><div class="modal-actions"><button class="btn secondary" id="gravityResultHome">ARCADE</button><button class="btn secondary" id="gravityResultSetup">SETUP</button>${finished?`<button class="btn secondary" id="gravityResultRecords">RECORDS</button>${!versus&&entries[0].details.completed&&level<30&&mode!=='survival'?'<button class="btn accent" id="gravityNextLevel">NEXT LEVEL →</button>':''}<button class="btn primary" id="gravityRematch">${versus?'REMATCH':'TRY AGAIN'} ↻</button>`:'<button class="btn primary" id="gravityNextRound">NEXT ROUND →</button>'}</div></div>`;
 $('#gravityResultHome').onclick=()=>{disposeWorlds();exit();};$('#gravityResultSetup').onclick=setup;if(finished){$('#gravityResultRecords').onclick=records;$('#gravityRematch').onclick=()=>{round=0;rounds=[];wins=[0,0];committed=false;requestSession();};if($('#gravityNextLevel'))$('#gravityNextLevel').onclick=()=>{level++;round=0;rounds=[];committed=false;requestSession();};}else $('#gravityNextRound').onclick=startRound;
 }
 function records(){disposeWorlds();page='records';phase='setup';const rows=DB.profiles.map(p=>{const list=p.results.filter(r=>r.game==='gravity'&&r.ruleset==='gravity-v1'&&r.levelId==='level-'+level&&r.difficulty===difficulty&&r.mode===(versus?'versus':'solo')&&r.competition===mode&&r.challengeKey==='series-'+(versus?series:1));const best=list.sort((a,b)=>Number(b.details.completed)-Number(a.details.completed)||(mode==='orbs'?b.details.orbs-a.details.orbs:mode==='survival'?b.duration-a.duration:0)||a.duration-b.duration||b.score-a.score)[0];return best?{p,r:best,high:Math.max(...list.map(r=>r.score))}:null;}).filter(Boolean).sort((a,b)=>Number(b.r.details.completed)-Number(a.r.details.completed)||(mode==='survival'?b.r.duration-a.r.duration:mode==='orbs'?b.r.details.orbs-a.r.details.orbs||a.r.duration-b.r.duration:a.r.duration-b.r.duration));
 content.innerHTML=`<div class="new-records"><div class="page-heading"><div><span class="eyebrow">GRAVITY CHAOS · REAL RUNS</span><h2>Make a little history.</h2><p>Every level, difficulty, challenge and match length has separate records.</p></div><button class="btn primary" id="gravityRecordsPlay">PLAY →</button></div><div class="gravity-record-filters"><label>Level<select id="gravityRecordLevel">${GRAVITY_LEVELS.map(l=>`<option value="${l.id}" ${level===l.id?'selected':''}>${l.id} · ${l.name}</option>`).join('')}</select></label><label>Difficulty<select id="gravityRecordDiff">${LEVELS.map((l,i)=>`<option value="${i+1}" ${difficulty===i+1?'selected':''}>${l}</option>`).join('')}</select></label><label>Mode<select id="gravityRecordMode">${Object.entries(GRAVITY_MODES).map(([key,name])=>`<option value="${key}" ${mode===key?'selected':''}>${name}</option>`).join('')}</select></label><label>Players<select id="gravityRecordPlayers"><option value="solo" ${!versus?'selected':''}>Solo</option><option value="versus" ${versus?'selected':''}>2 players</option></select></label>${versus?`<label>Match<select id="gravityRecordSeries"><option value="1" ${series===1?'selected':''}>Single round</option><option value="5" ${series===5?'selected':''}>Best of five</option></select></label>`:''}</div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>PLAYER</th><th>BEST TIME</th><th>ORBS</th><th>FEWEST FLIPS</th><th>HIGH SCORE</th><th>MISTAKES</th></tr></thead><tbody>${rows.map(({p,r,high})=>{const rs=p.results.filter(x=>recordKey(x)===recordKey(r)&&x.details.completed),flips=rs.length?Math.min(...rs.map(r=>r.details.changes)):'—';return `<tr><td>${p.avatar} ${esc(p.name)}</td><td>${r.details.completed||mode==='survival'?r.duration.toFixed(1)+'s':'Incomplete'}</td><td>${r.details.orbs}</td><td>${flips}</td><td>${high}</td><td>${r.errors}</td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty-state"><h2>Your first orbit belongs here.</h2><p>Finish a run in this exact mode to save a real record.</p></div>'}<div class="gravity-family-summary">${DB.profiles.map(p=>{const rs=p.results.filter(r=>r.game==='gravity'),ds=rs.flatMap(r=>r.details?.rounds||[r.details]).filter(Boolean),complete=ds.filter(d=>d.completed);return `<article class="panel"><span class="avatar" style="--player:${p.color}">${p.avatar}</span><h3>${esc(p.name)}</h3><p>${new Set(rs.filter(r=>(r.details?.rounds||[r.details]).some(d=>d?.completed)).map(r=>r.levelId)).size} levels completed<br>${ds.reduce((sum,d)=>sum+d.orbs,0)} energy orbs collected<br>${complete.filter(d=>d.perfect).length} perfect runs<br>${rs.filter(r=>r.mode==='versus'&&r.win).length} multiplayer wins</p></article>`;}).join('')}</div></div>`;
 $('#gravityRecordsPlay').onclick=setup;for(const [id,fn]of [['gravityRecordLevel',v=>level=+v],['gravityRecordDiff',v=>difficulty=+v],['gravityRecordMode',v=>mode=v],['gravityRecordPlayers',v=>versus=v==='versus'],['gravityRecordSeries',v=>series=+v]])if($('#'+id))$('#'+id).onchange=e=>{fn(e.target.value);records();};
 }
 function visibility(){if(document.hidden)pause(true);}document.addEventListener('visibilitychange',visibility);if(initialPage==='records')records();else setup();raf=requestAnimationFrame(frame);
 return()=>{disposed=true;gate.dispose();cancelAnimationFrame(raf);disposeWorlds();document.removeEventListener('visibilitychange',visibility);};
}
export function gravityArt(){return coverArt('gravity')|| `<svg viewBox="0 0 500 230"><defs><radialGradient id="gravityBall"><stop stop-color="#efffff"/><stop offset=".45" stop-color="#8aeaff"/><stop offset="1" stop-color="#8f85fc"/></radialGradient></defs><rect x="65" y="25" width="370" height="190" rx="30" fill="#172e49" stroke="#526b91" stroke-width="3"/><path d="M65 160h250M185 87h250" stroke="#637eaa" stroke-width="13"/><path d="M91 163h82" stroke="#66edcb" stroke-width="7"/><circle cx="360" cy="137" r="24" fill="url(#gravityBall)"/><path d="M313 136h-38m18-20l-20 20 20 20" fill="none" stroke="#8fe9f4" stroke-width="6" stroke-linecap="round"/><path d="M140 72v-30m-15 15l15-15 15 15" fill="none" stroke="#b399f4" stroke-width="5" stroke-linecap="round"/><circle cx="111" cy="113" r="14" fill="#fbdc88"/><circle cx="383" cy="48" r="16" fill="none" stroke="#66ecc8" stroke-width="5"/><circle cx="270" cy="190" r="11" fill="#af97ff"/></svg>`;}
function rounded(c,x,y,w,h,r,fill,stroke){c.beginPath();c.roundRect(x,y,w,h,r);if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.lineWidth=2;c.strokeStyle=stroke;c.stroke();}}
function text(c,s,x,y,size=14,color='#d5e9ff'){c.fillStyle=color;c.font=`600 ${size}px Outfit,Arial`;c.textAlign='center';c.textBaseline='middle';c.fillText(s,x,y);}
export function renderGravity(canvas,w,color='#89bfff'){
 const{c}=prepareCanvas(canvas),phase=w.clock/1000,g=c.createLinearGradient(0,0,1000,640);g.addColorStop(0,'#12293b');g.addColorStop(1,'#2b254d');c.fillStyle=g;c.fillRect(0,0,1000,640);drawBackdrop(c,'gravity machinery',w.clock);c.strokeStyle='#92bae918';c.lineWidth=1;for(let x=0;x<=1000;x+=40){c.beginPath();c.moveTo(x,0);c.lineTo(x,640);c.stroke();}for(let y=0;y<=640;y+=40){c.beginPath();c.moveTo(0,y);c.lineTo(1000,y);c.stroke();}text(c,w.level.theme.toUpperCase(),500,35,13,'#88bfd8');
 const dir=DIRECTIONS[w.direction];c.globalAlpha=.07;text(c,dir.icon,500,330,240,'#a5cdff');c.globalAlpha=1;
 for(const z of w.zones){if(z.kind==='shield'&&w.collected.has(z.id))continue;c.fillStyle={slow:'#bd9bff18',boost:'#ffd27618',teleport:'#9a93ff26',shield:'#70e2e530'}[z.kind];c.strokeStyle={slow:'#b299ec',boost:'#eec779',teleport:'#a794f2',shield:'#71e5d9'}[z.kind];c.lineWidth=2;c.beginPath();c.arc(z.x,z.y,z.r,0,Math.PI*2);c.fill();c.stroke();text(c,{slow:'◷',boost:'↑↑',teleport:'◎',shield:'⬡'}[z.kind],z.x,z.y,23,c.strokeStyle);if(z.kind==='teleport'){c.setLineDash([5,6]);c.beginPath();c.arc(z.dest.x,z.dest.y,23,0,Math.PI*2);c.stroke();c.setLineDash([]);}}
 if(w.level.rampZone){const z=w.level.rampZone;c.setLineDash([7,8]);rounded(c,z.x,z.y,z.w,z.h,15,'#82c5fc08','#8ba7dd66');c.setLineDash([]);text(c,'DRAW RAMP HERE',z.x+z.w/2,z.y+z.h-16,11,'#aabde6');}
 const palette={wall:'#526780',moving:'#678bb7',platform:'#ac87dc',door:'#d1a05f',timed:'#d697b0',blade:'#eea3b7',crush:'#b085b3',block:'#809db9',magnet:'#9d8ac8',bounce:'#55d6b3',conveyor:'#73d7ce',ramp:'#80c8f3'};
 for(const b of [...w.bodies,...w.ramps.map(r=>r.body)]){const s=b.plugin.gravity;if(b.plugin.off){c.globalAlpha=.18;}if(s.kind==='laser'||s.kind==='chaos'){c.strokeStyle=s.kind==='chaos'?'#c196ff':'#ff8eae';c.lineWidth=s.kind==='chaos'?7:5;c.shadowBlur=b.plugin.off?0:13;c.shadowColor=c.strokeStyle;c.beginPath();if(s.kind==='chaos'){c.moveTo(b.position.x,12);c.lineTo(b.position.x,628);}else{c.moveTo(b.position.x-s.w/2,b.position.y);c.lineTo(b.position.x+s.w/2,b.position.y);}c.stroke();c.shadowBlur=0;c.globalAlpha=1;continue;}
 if(s.kind==='bumper'){const flash=w.bumperFlashes.get(s.id)>w.clock;c.shadowColor='#f6d68b';c.shadowBlur=flash?25:8;c.fillStyle=flash?'#fff0bc':'#dfb66e';c.beginPath();c.arc(b.position.x,b.position.y,b.circleRadius,0,Math.PI*2);c.fill();c.shadowBlur=0;text(c,'✦',b.position.x,b.position.y,25,'#5a4674');c.globalAlpha=1;continue;}
 c.save();c.translate(b.position.x,b.position.y);c.rotate(b.angle);if(s.kind==='spikes'){c.fillStyle='#f6a2b5';for(let x=-s.w/2;x<s.w/2;x+=18){c.beginPath();c.moveTo(x,s.h/2);c.lineTo(x+9,-s.h/2);c.lineTo(x+18,s.h/2);c.fill();}}else{rounded(c,-s.w/2,-s.h/2,s.w,s.h,Math.min(7,s.h/3),palette[s.kind]||'#5e7092',s.kind==='platform'?'#dfbdff':'#bdc8e144');if(['wall','moving','platform','block','crush','magnet','conveyor','door'].includes(s.kind))drawMaterial(c,s.kind==='block'?'stone':'metal',-s.w/2,-s.h/2,s.w,s.h,{time:w.clock});if(s.kind==='platform'){text(c,s.rotatable?'↔  ⟳':'↔',0,0,13,'#2e2b51');}if(s.kind==='bounce')text(c,'▲ ▲ ▲',0,0,12,'#1e5b57');if(s.kind==='block')text(c,'◈',0,0,18,'#c8e6fa');if(s.kind==='door')text(c,'A',0,0,13,'#422f40');if(s.kind==='blade')text(c,'✧',0,0,17,'#693e65');}c.restore();c.globalAlpha=1;}
 for(const p of w.level.checkpoints){c.strokeStyle=w.checkpointIndex>=0?'#66e8c9':'#8b9edc55';c.lineWidth=2;c.beginPath();c.arc(p.x,p.y,27,0,Math.PI*2);c.stroke();text(c,'⚑',p.x,p.y,22,c.strokeStyle);}
 for(const o of w.level.orbs){if(w.collected.has(o.id))continue;const y=o.y+Math.sin(phase*3)*2;c.shadowBlur=12;c.shadowColor=o.required?'#ffdc84':'#a8c9f2';c.fillStyle=c.shadowColor;c.beginPath();c.arc(o.x,y,o.required?10:8,0,Math.PI*2);c.fill();c.shadowBlur=0;if(o.required){c.strokeStyle='#ffe8a0';c.beginPath();c.arc(o.x,y,16,0,Math.PI*2);c.stroke();}}
 for(const s of w.level.switches){const on=w.switches.has(s.id);rounded(c,s.x-23,s.y-23,46,46,14,on?'#5fcab0':'#d6b66d',on?'#a4f7d6':'#ffe0a4');text(c,s.id,s.x,s.y,20,on?'#174d49':'#46314b');text(c,on?'GATE ON':'TAP SWITCH',s.x,s.y+34,10,'#c7dde8');}
 const goal=w.level.goal;c.shadowBlur=w.goalOpen?18:0;c.shadowColor='#60e6cc';c.strokeStyle=w.goalOpen?'#7bf4d2':'#8796c6';c.lineWidth=5;c.beginPath();c.arc(goal.x,goal.y,goal.r,0,Math.PI*2);c.stroke();c.shadowBlur=0;text(c,w.goalOpen?'◎':'🔒',goal.x,goal.y,20,w.goalOpen?'#a4ffe3':'#c7b8de');
 for(let i=0;i<w.trail.length;i++){const p=w.trail[i];c.globalAlpha=i/w.trail.length*.35;c.fillStyle=color;c.beginPath();c.arc(p.x,p.y,3+i/w.trail.length*5,0,Math.PI*2);c.fill();}c.globalAlpha=1;
 for(const p of w.particles){c.globalAlpha=p.life/400;c.fillStyle='#d7f6ff';c.fillRect(p.x,p.y,3,3);}c.globalAlpha=1;
 const p=w.ball.position;c.shadowColor='#7bdfff';c.shadowBlur=24;const glow=c.createRadialGradient(p.x-4,p.y-5,1,p.x,p.y,16);glow.addColorStop(0,'#f3ffff');glow.addColorStop(.45,'#93eaff');glow.addColorStop(1,'#9698f9');c.fillStyle=glow;c.beginPath();c.arc(p.x,p.y,w.ball.circleRadius,0,Math.PI*2);c.fill();c.shadowBlur=0;if(w.clock<w.shieldUntil||w.clock<w.safeUntil){c.strokeStyle='#a4ffde';c.lineWidth=2;c.beginPath();c.arc(p.x,p.y,22,0,Math.PI*2);c.stroke();}
 if(w.rampPreview.length===2){c.strokeStyle='#b0ddff';c.lineWidth=7;c.setLineDash([9,5]);c.beginPath();c.moveTo(w.rampPreview[0].x,w.rampPreview[0].y);c.lineTo(w.rampPreview[1].x,w.rampPreview[1].y);c.stroke();c.setLineDash([]);}
 for(const pointer of w.pointers.values())if(pointer.kind==='swipe'){c.strokeStyle='#c1ddff88';c.lineWidth=4;c.beginPath();c.moveTo(pointer.start.x,pointer.start.y);c.lineTo(pointer.point.x,pointer.point.y);c.stroke();}
}
